payload.template:
module edge_detect (
  input  logic clk,
  input  logic rst,
  input  logic din,
  output logic rise
);

  // your code here: remember what din was on the previous rising edge,
  // and drive rise high for exactly one cycle after din goes 0 -> 1.
  //
  // rise is registered: it appears one cycle after the change, not in
  // the same cycle. Clocked logic, so non-blocking assignment.

endmodule

payload.testbench:
`timescale 1ns/1ps
// The sample testbench. Run uses this one; Submit uses a different
// one that tries cases this does not.
module tb;
  logic clk = 1'b0, rst = 1'b1, din = 1'b0, rise;
  int pulses = 0;

  edge_detect dut (.clk(clk), .rst(rst), .din(din), .rise(rise));

  always #5 clk = ~clk;

  // Count every cycle in which rise is high, sampled away from the edge.
  always @(negedge clk) if (rise) pulses++;

  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb);

    @(posedge clk); @(negedge clk);
    $display("CHECK after_reset 0 %b AT %0d", rise, $time);
    rst = 1'b0;

    // din rises during this cycle...
    @(negedge clk) din = 1'b1;
    // ...so rise should be high in the NEXT one.
    @(posedge clk); #1;
    $display("CHECK one_cycle_later 1 %b AT %0d", rise, $time);

    // and low again in the one after that, with din still high.
    @(posedge clk); #1;
    $display("CHECK single_pulse 0 %b AT %0d", rise, $time);

    // A falling edge is not an edge we care about.
    @(negedge clk) din = 1'b0;
    @(posedge clk); #1;
    $display("CHECK no_fall 0 %b AT %0d", rise, $time);

    repeat (2) @(posedge clk);
    @(negedge clk); #1;
    $display("CHECK total 1 %0d AT %0d", pulses, $time);
    $display("DONE 5");
    $finish;
  end
endmodule
